import type { Subscription } from "@/types/subscription";
import type { SubscriptionInput, SubscriptionPatch } from "@/lib/validation/subscription";
import { toISODate } from "@/lib/domain/dates";
import { nextChargeOnOrAfter } from "@/lib/domain/renewal";
import { DEMO_USER_ID, type SubscriptionRepository } from "../types";
import { seedSubscriptions } from "./seed";

// In-memory store. Persists for the lifetime of the server process (dev use).
const store = new Map<string, Subscription>();
for (const sub of seedSubscriptions()) store.set(sub.id, sub);
let sequence = store.size;

function computeNextRenewal(sub: Subscription): string {
  const anchor = sub.isTrial && sub.freeTrialEndAt ? sub.freeTrialEndAt : sub.startDate;
  const nextDate =
    nextChargeOnOrAfter(anchor, sub.billingCycle, sub.intervalCount, toISODate(new Date())) ??
    sub.startDate;
  const time = /^\d{2}:\d{2}$/.test(sub.reminderTimeLocal) ? sub.reminderTimeLocal : "09:00";
  return `${nextDate}T${time}:00.000Z`;
}

function nextId(): string {
  return `sub_${(++sequence).toString().padStart(3, "0")}`;
}

function applyPatch(target: Subscription, patch: SubscriptionPatch): void {
  if (patch.name !== undefined) target.name = patch.name;
  if (patch.provider !== undefined) target.provider = patch.provider ?? null;
  if (patch.category !== undefined) target.category = patch.category;
  if (patch.amount !== undefined) target.amount = patch.amount;
  if (patch.currency !== undefined) target.currency = patch.currency;
  if (patch.billingCycle !== undefined) target.billingCycle = patch.billingCycle;
  if (patch.intervalCount !== undefined) target.intervalCount = patch.intervalCount;
  if (patch.planType !== undefined) target.planType = patch.planType ?? null;
  if (patch.startDate !== undefined) target.startDate = patch.startDate;
  if (patch.freeTrialEndAt !== undefined) target.freeTrialEndAt = patch.freeTrialEndAt ?? null;
  if (patch.isTrial !== undefined) target.isTrial = patch.isTrial;
  if (patch.unsubscribeUrl !== undefined) {
    target.unsubscribeUrl = patch.unsubscribeUrl ? patch.unsubscribeUrl : null;
  }
  if (patch.color !== undefined) target.color = patch.color ?? null;
  if (patch.notes !== undefined) target.notes = patch.notes ?? null;
  if (patch.reminderOffsetsDays !== undefined) {
    target.reminderOffsetsDays = patch.reminderOffsetsDays;
  }
  if (patch.reminderTimeLocal !== undefined) target.reminderTimeLocal = patch.reminderTimeLocal;
  if (patch.notificationChannels !== undefined) {
    target.notificationChannels = patch.notificationChannels;
  }
}

function ownedBy(userId: string, id: string): Subscription | null {
  const sub = store.get(id);
  return sub && sub.userId === userId ? sub : null;
}

export const mockSubscriptionRepository: SubscriptionRepository = {
  async list(userId) {
    return [...store.values()]
      .filter((sub) => sub.userId === userId)
      .sort((a, b) => a.nextRenewalAt.localeCompare(b.nextRenewalAt));
  },

  async get(userId, id) {
    return ownedBy(userId, id);
  },

  async create(userId, input: SubscriptionInput) {
    const timestamp = new Date().toISOString();
    const sub: Subscription = {
      id: nextId(),
      userId,
      name: input.name,
      provider: input.provider ?? input.name,
      category: input.category,
      amount: input.amount,
      currency: input.currency,
      billingCycle: input.billingCycle,
      intervalCount: input.intervalCount,
      planType: input.planType ?? null,
      startDate: input.startDate,
      nextRenewalAt: "",
      freeTrialEndAt: input.freeTrialEndAt ?? null,
      isTrial: input.isTrial,
      isPaused: false,
      isCancelled: false,
      unsubscribeUrl: input.unsubscribeUrl ? input.unsubscribeUrl : null,
      iconType: "monogram",
      iconUrl: null,
      color: input.color ?? null,
      notes: input.notes ?? null,
      reminderOffsetsDays: input.reminderOffsetsDays,
      reminderTimeLocal: input.reminderTimeLocal,
      notificationChannels: input.notificationChannels,
      createdAt: timestamp,
      updatedAt: timestamp,
    };
    sub.nextRenewalAt = computeNextRenewal(sub);
    store.set(sub.id, sub);
    return sub;
  },

  async update(userId, id, patch) {
    const current = ownedBy(userId, id);
    if (!current) return null;
    applyPatch(current, patch);
    current.updatedAt = new Date().toISOString();
    current.nextRenewalAt = computeNextRenewal(current);
    store.set(id, current);
    return current;
  },

  async remove(userId, id) {
    if (!ownedBy(userId, id)) return false;
    return store.delete(id);
  },

  async setPaused(userId, id, paused) {
    const current = ownedBy(userId, id);
    if (!current) return null;
    current.isPaused = paused;
    current.updatedAt = new Date().toISOString();
    store.set(id, current);
    return current;
  },

  async setCancelled(userId, id, cancelled) {
    const current = ownedBy(userId, id);
    if (!current) return null;
    current.isCancelled = cancelled;
    current.updatedAt = new Date().toISOString();
    store.set(id, current);
    return current;
  },
};

export { DEMO_USER_ID };

