import { mockSubscriptionRepository } from "./mock/mock-repo";
import type { SubscriptionRepository } from "./types";

export { DEMO_USER_ID } from "./types";
export type { SubscriptionRepository } from "./types";

const dataSource = process.env.NEXT_PUBLIC_DATA_SOURCE ?? "mock";

export function isSupabaseEnabled(): boolean {
  return dataSource === "supabase";
}

/**
 * Returns the active subscription repository. With `NEXT_PUBLIC_DATA_SOURCE=supabase`
 * it builds a Supabase-backed repo bound to the request's auth cookies; otherwise
 * it returns the in-memory mock seeded with demo data. Both satisfy the same
 * `SubscriptionRepository` contract, so callers never change.
 */
export async function getSubscriptionRepository(): Promise<SubscriptionRepository> {
  if (isSupabaseEnabled()) {
    const [{ createSupabaseServerClient }, { createSupabaseSubscriptionRepository }] =
      await Promise.all([
        import("@/lib/supabase/server"),
        import("./supabase/supabase-repo"),
      ]);
    const client = await createSupabaseServerClient();
    return createSupabaseSubscriptionRepository(client);
  }
  return mockSubscriptionRepository;
}

import type { Subscription } from "@/types/subscription";
import type { SubscriptionInput } from "@/lib/validation/subscription";
import {
  applySubscriptionPatch,
  computeNextRenewalInstant,
} from "@/lib/domain/subscription";
import { DEMO_USER_ID, type SubscriptionRepository } from "../types";
import { seedSubscriptions } from "./seed";

// In-memory store. Persists for the lifetime of the server process (dev use).
const store = new Map<string, Subscription>();
for (const sub of seedSubscriptions()) store.set(sub.id, sub);
let sequence = store.size;

function nextId(): string {
  return `sub_${(++sequence).toString().padStart(3, "0")}`;
}

function ownedBy(userId: string, id: string): Subscription | null {
  const sub = store.get(id);
  return sub && sub.userId === userId ? sub : null;
}

export const mockSubscriptionRepository: SubscriptionRepository = {
  async list(userId) {
    return [...store.values()]
      .filter((sub) => sub.userId === userId)
      .sort((a, b) => a.nextRenewalAt.localeCompare(b.nextRenewalAt));
  },

  async get(userId, id) {
    return ownedBy(userId, id);
  },

  async create(userId, input: SubscriptionInput) {
    const timestamp = new Date().toISOString();
    const sub: Subscription = {
      id: nextId(),
      userId,
      name: input.name,
      provider: input.provider ?? input.name,
      category: input.category,
      amount: input.amount,
      currency: input.currency,
      billingCycle: input.billingCycle,
      intervalCount: input.intervalCount,
      planType: input.planType ?? null,
      startDate: input.startDate,
      nextRenewalAt: "",
      freeTrialEndAt: input.freeTrialEndAt ?? null,
      isTrial: input.isTrial,
      isPaused: false,
      isCancelled: false,
      unsubscribeUrl: input.unsubscribeUrl ? input.unsubscribeUrl : null,
      iconType: "monogram",
      iconUrl: null,
      color: input.color ?? null,
      notes: input.notes ?? null,
      reminderOffsetsDays: input.reminderOffsetsDays,
      reminderTimeLocal: input.reminderTimeLocal,
      notificationChannels: input.notificationChannels,
      createdAt: timestamp,
      updatedAt: timestamp,
    };
    sub.nextRenewalAt = computeNextRenewalInstant(sub);
    store.set(sub.id, sub);
    return sub;
  },

  async update(userId, id, patch) {
    const current = ownedBy(userId, id);
    if (!current) return null;
    applySubscriptionPatch(current, patch);
    current.updatedAt = new Date().toISOString();
    current.nextRenewalAt = computeNextRenewalInstant(current);
    store.set(id, current);
    return current;
  },

  async remove(userId, id) {
    if (!ownedBy(userId, id)) return false;
    return store.delete(id);
  },

  async setPaused(userId, id, paused) {
    const current = ownedBy(userId, id);
    if (!current) return null;
    current.isPaused = paused;
    current.updatedAt = new Date().toISOString();
    store.set(id, current);
    return current;
  },

  async setCancelled(userId, id, cancelled) {
    const current = ownedBy(userId, id);
    if (!current) return null;
    current.isCancelled = cancelled;
    current.updatedAt = new Date().toISOString();
    store.set(id, current);
    return current;
  },
};

export { DEMO_USER_ID };

import type { SupabaseClient } from "@supabase/supabase-js";
import type { BillingCycle, Category, CurrencyCode } from "@/lib/constants";
import type { Database } from "@/lib/supabase/types";
import type { IconType, NotificationChannel, Subscription } from "@/types/subscription";
import type { SubscriptionInput, SubscriptionPatch } from "@/lib/validation/subscription";
import {
  applySubscriptionPatch,
  computeNextRenewalInstant,
} from "@/lib/domain/subscription";
import type { SubscriptionRepository } from "../types";

type Row = Database["public"]["Tables"]["subscriptions"]["Row"];
type Insert = Database["public"]["Tables"]["subscriptions"]["Insert"];
type UpdateRow = Database["public"]["Tables"]["subscriptions"]["Update"];

function rowToSubscription(row: Row): Subscription {
  return {
    id: row.id,
    userId: row.user_id,
    name: row.name,
    provider: row.provider,
    category: row.category as Category,
    amount: Number(row.amount),
    currency: row.currency as CurrencyCode,
    billingCycle: row.billing_cycle as BillingCycle,
    intervalCount: row.interval_count,
    planType: row.plan_type,
    startDate: row.start_date,
    nextRenewalAt: row.next_renewal_at ?? `${row.start_date}T09:00:00.000Z`,
    freeTrialEndAt: row.free_trial_end_at,
    isTrial: row.is_trial,
    isPaused: row.is_paused,
    isCancelled: row.is_cancelled,
    unsubscribeUrl: row.unsubscribe_url,
    iconType: (row.icon_type as IconType) ?? "monogram",
    iconUrl: row.icon_url,
    color: row.color,
    notes: row.notes,
    reminderOffsetsDays: row.reminder_offsets_days ?? [],
    reminderTimeLocal: row.reminder_time_local,
    notificationChannels: (row.notification_channels ?? []) as NotificationChannel[],
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Mutable columns only — id/user_id/timestamps are managed elsewhere. */
function subscriptionToColumns(sub: Subscription): UpdateRow {
  return {
    name: sub.name,
    provider: sub.provider,
    category: sub.category,
    amount: sub.amount,
    currency: sub.currency,
    billing_cycle: sub.billingCycle,
    interval_count: sub.intervalCount,
    plan_type: sub.planType,
    start_date: sub.startDate,
    next_renewal_at: sub.nextRenewalAt,
    free_trial_end_at: sub.freeTrialEndAt,
    is_trial: sub.isTrial,
    is_paused: sub.isPaused,
    is_cancelled: sub.isCancelled,
    unsubscribe_url: sub.unsubscribeUrl,
    icon_type: sub.iconType,
    icon_url: sub.iconUrl,
    color: sub.color,
    notes: sub.notes,
    reminder_offsets_days: sub.reminderOffsetsDays,
    reminder_time_local: sub.reminderTimeLocal,
    notification_channels: sub.notificationChannels,
  };
}

/**
 * Supabase-backed repository. RLS enforces ownership; we additionally filter by
 * user_id as defense in depth. Requires an authenticated server client.
 */
export function createSupabaseSubscriptionRepository(
  client: SupabaseClient<Database>,
): SubscriptionRepository {
  const table = () => client.from("subscriptions");

  return {
    async list(userId) {
      const { data, error } = await table()
        .select("*")
        .eq("user_id", userId)
        .order("next_renewal_at", { ascending: true });
      if (error) throw error;
      return (data ?? []).map(rowToSubscription);
    },

    async get(userId, id) {
      const { data, error } = await table()
        .select("*")
        .eq("id", id)
        .eq("user_id", userId)
        .maybeSingle();
      if (error) throw error;
      return data ? rowToSubscription(data) : null;
    },

    async create(userId, input: SubscriptionInput) {
      const nextRenewalAt = computeNextRenewalInstant({
        startDate: input.startDate,
        isTrial: input.isTrial,
        freeTrialEndAt: input.freeTrialEndAt ?? null,
        billingCycle: input.billingCycle,
        intervalCount: input.intervalCount,
        reminderTimeLocal: input.reminderTimeLocal,
      });
      const insert: Insert = {
        user_id: userId,
        name: input.name,
        provider: input.provider ?? input.name,
        category: input.category,
        amount: input.amount,
        currency: input.currency,
        billing_cycle: input.billingCycle,
        interval_count: input.intervalCount,
        plan_type: input.planType ?? null,
        start_date: input.startDate,
        next_renewal_at: nextRenewalAt,
        free_trial_end_at: input.freeTrialEndAt ?? null,
        is_trial: input.isTrial,
        is_paused: false,
        is_cancelled: false,
        unsubscribe_url: input.unsubscribeUrl ? input.unsubscribeUrl : null,
        icon_type: "monogram",
        color: input.color ?? null,
        notes: input.notes ?? null,
        reminder_offsets_days: input.reminderOffsetsDays,
        reminder_time_local: input.reminderTimeLocal,
        notification_channels: input.notificationChannels,
      };
      const { data, error } = await table().insert(insert).select("*").single();
      if (error) throw error;
      return rowToSubscription(data);
    },

    async update(userId, id, patch: SubscriptionPatch) {
      const { data: existing, error: fetchError } = await table()
        .select("*")
        .eq("id", id)
        .eq("user_id", userId)
        .maybeSingle();
      if (fetchError) throw fetchError;
      if (!existing) return null;

      const merged = rowToSubscription(existing);
      applySubscriptionPatch(merged, patch);
      merged.nextRenewalAt = computeNextRenewalInstant(merged);

      const { data, error } = await table()
        .update(subscriptionToColumns(merged))
        .eq("id", id)
        .eq("user_id", userId)
        .select("*")
        .single();
      if (error) throw error;
      return rowToSubscription(data);
    },

    async remove(userId, id) {
      const { data, error } = await table()
        .delete()
        .eq("id", id)
        .eq("user_id", userId)
        .select("id");
      if (error) throw error;
      return (data?.length ?? 0) > 0;
    },

    async setPaused(userId, id, paused) {
      const { data, error } = await table()
        .update({ is_paused: paused })
        .eq("id", id)
        .eq("user_id", userId)
        .select("*")
        .maybeSingle();
      if (error) throw error;
      return data ? rowToSubscription(data) : null;
    },

    async setCancelled(userId, id, cancelled) {
      const { data, error } = await table()
        .update({ is_cancelled: cancelled })
        .eq("id", id)
        .eq("user_id", userId)
        .select("*")
        .maybeSingle();
      if (error) throw error;
      return data ? rowToSubscription(data) : null;
    },
  };
}

import type { BillingCycle } from "@/lib/constants";
import type { Subscription, SubscriptionStatus } from "@/types/subscription";
import type { SubscriptionPatch } from "@/lib/validation/subscription";
import { daysUntil, toISODate } from "./dates";
import { monthlyEquivalent, yearlyEquivalent } from "./money";
import { chargesInRange, nextChargeOnOrAfter } from "./renewal";

/** The date the recurring charge series is anchored to. */
export function chargeAnchorISO(sub: Subscription): string {
  return sub.isTrial && sub.freeTrialEndAt ? sub.freeTrialEndAt : sub.startDate;
}

export function getStatus(sub: Subscription): SubscriptionStatus {
  if (sub.isCancelled) return "cancelled";
  if (sub.isPaused) return "paused";
  if (sub.isTrial && sub.freeTrialEndAt && daysUntil(sub.freeTrialEndAt) >= 0) {
    return "trial";
  }
  return "active";
}

export function isActive(sub: Subscription): boolean {
  return !sub.isCancelled && !sub.isPaused;
}

/** Next real charge date (civil), or null if paused/cancelled/expired one-off. */
export function getNextChargeDate(
  sub: Subscription,
  fromISO: string = toISODate(new Date()),
): string | null {
  if (!isActive(sub)) return null;
  return nextChargeOnOrAfter(chargeAnchorISO(sub), sub.billingCycle, sub.intervalCount, fromISO);
}

/** Normalized monthly cost; paused/cancelled subs contribute nothing. */
export function monthlyAmount(sub: Subscription): number {
  if (!isActive(sub)) return 0;
  return monthlyEquivalent(sub.amount, sub.billingCycle, sub.intervalCount);
}

export function yearlyAmount(sub: Subscription): number {
  if (!isActive(sub)) return 0;
  return yearlyEquivalent(sub.amount, sub.billingCycle, sub.intervalCount);
}

/** Charge dates for an active subscription within a civil-date range. */
export function chargeDatesInRange(
  sub: Subscription,
  startISO: string,
  endISO: string,
): string[] {
  if (!isActive(sub)) return [];
  return chargesInRange(
    chargeAnchorISO(sub),
    sub.billingCycle,
    sub.intervalCount,
    startISO,
    endISO,
  );
}

export function isTrialConvertingWithin(sub: Subscription, days: number): boolean {
  if (!sub.isTrial || !sub.freeTrialEndAt || !isActive(sub)) return false;
  const d = daysUntil(sub.freeTrialEndAt);
  return d >= 0 && d <= days;
}

/** Two-letter monogram used when no provider icon is available. */
export function getMonogram(sub: Subscription): string {
  const source = (sub.provider || sub.name).trim();
  const parts = source.split(/\s+/).filter(Boolean);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return source.slice(0, 2).toUpperCase() || "??";
}

/** Fields needed to derive the cached `next_renewal_at` instant. */
export interface RenewalFields {
  startDate: string;
  isTrial: boolean;
  freeTrialEndAt: string | null;
  billingCycle: BillingCycle;
  intervalCount: number;
  reminderTimeLocal: string;
}

/** Compute the cached next-renewal instant (UTC ISO) from renewal fields. */
export function computeNextRenewalInstant(fields: RenewalFields): string {
  const anchor = fields.isTrial && fields.freeTrialEndAt ? fields.freeTrialEndAt : fields.startDate;
  const nextDate =
    nextChargeOnOrAfter(anchor, fields.billingCycle, fields.intervalCount, toISODate(new Date())) ??
    fields.startDate;
  const time = /^\d{2}:\d{2}$/.test(fields.reminderTimeLocal) ? fields.reminderTimeLocal : "09:00";
  return `${nextDate}T${time}:00.000Z`;
}

/** Apply a validated patch onto a subscription in place (shared by repos). */
export function applySubscriptionPatch(target: Subscription, patch: SubscriptionPatch): void {
  if (patch.name !== undefined) target.name = patch.name;
  if (patch.provider !== undefined) target.provider = patch.provider ?? null;
  if (patch.category !== undefined) target.category = patch.category;
  if (patch.amount !== undefined) target.amount = patch.amount;
  if (patch.currency !== undefined) target.currency = patch.currency;
  if (patch.billingCycle !== undefined) target.billingCycle = patch.billingCycle;
  if (patch.intervalCount !== undefined) target.intervalCount = patch.intervalCount;
  if (patch.planType !== undefined) target.planType = patch.planType ?? null;
  if (patch.startDate !== undefined) target.startDate = patch.startDate;
  if (patch.freeTrialEndAt !== undefined) target.freeTrialEndAt = patch.freeTrialEndAt ?? null;
  if (patch.isTrial !== undefined) target.isTrial = patch.isTrial;
  if (patch.unsubscribeUrl !== undefined) {
    target.unsubscribeUrl = patch.unsubscribeUrl ? patch.unsubscribeUrl : null;
  }
  if (patch.color !== undefined) target.color = patch.color ?? null;
  if (patch.notes !== undefined) target.notes = patch.notes ?? null;
  if (patch.reminderOffsetsDays !== undefined) target.reminderOffsetsDays = patch.reminderOffsetsDays;
  if (patch.reminderTimeLocal !== undefined) target.reminderTimeLocal = patch.reminderTimeLocal;
  if (patch.notificationChannels !== undefined) {
    target.notificationChannels = patch.notificationChannels;
  }
}
